/** The palette for light or dark; its high-contrast one when the system asks for more contrast. */
fun scribeColors(dark: Boolean, highContrast: Boolean): ScribeColors = when {
    highContrast && dark -> ScribeHighContrastColors
    highContrast -> ScribeHighContrastLightColors
    dark -> ScribeDarkColors
    else -> ScribeLightColors
}

/** Maps the roles onto Material 3 so stock components look like Fretscribe. */
fun ScribeColors.toColorScheme(dark: Boolean): ColorScheme {
    val scheme = if (dark) darkColorScheme() else lightColorScheme()
    return scheme.copy(
        primary = primary, onPrimary = onPrimary,
        primaryContainer = secondary, onPrimaryContainer = onSecondary, inversePrimary = brand,
        secondary = text, onSecondary = bg,
        secondaryContainer = secondary, onSecondaryContainer = onSecondary,
        tertiary = brandText, onTertiary = onPrimary,
        tertiaryContainer = brandTint, onTertiaryContainer = text,
        background = bg, onBackground = text,
        surface = bg, onSurface = text, surfaceVariant = surface, onSurfaceVariant = textMuted,
        surfaceTint = bg, inverseSurface = text, inverseOnSurface = bg,
        error = error, onError = bg, errorContainer = surface, onErrorContainer = error,
        outline = borderStrong, outlineVariant = border, scrim = Color.Black,
        surfaceBright = surfaceRaised, surfaceDim = surface,
        surfaceContainerLowest = surfaceRaised, surfaceContainerLow = surfaceRaised,
        surfaceContainer = surface, surfaceContainerHigh = surfaceRaised, surfaceContainerHighest = secondary,
    )
}

/** The type ramp as Material 3 roles. Sizes are sp, so they follow the system font scale. */
