val LocalScribeColors = staticCompositionLocalOf { ScribeLightColors }

/** The system contrast level; 0.5 and above is treated as high contrast. */
@Composable
fun systemHighContrast(): Boolean {
    val context = LocalContext.current
    val ui = context.getSystemService(UiModeManager::class.java) ?: return false
    return ui.contrast >= 0.5f
}

/**
 * Fretscribe on Material 3. Dynamic colour is deliberately not used: the palette is fixed for
 * accessibility and the brand stays the same on every device.
 *
 * @param display the brand display face; pass FontFamily(Font(R.font.atkinson_hyperlegible_next)) after copying
 *   design/fretscribe/dist/android/res/font into the app. Defaults to the system serif.
 * @param colors the palette: the one for [dark] and [highContrast], or another of the brand's own that it passes.
 */
@Composable
fun ScribeTheme(
    dark: Boolean = isSystemInDarkTheme(),
    highContrast: Boolean = systemHighContrast(),
    display: FontFamily = FontFamily.Serif,
    colors: ScribeColors = scribeColors(dark, highContrast),
    content: @Composable () -> Unit,
) {
    CompositionLocalProvider(LocalScribeColors provides colors) {
        MaterialTheme(
            colorScheme = colors.toColorScheme(dark = dark),
            typography = scribeTypography(display),
            shapes = ScribeShapes,
            content = content,
        )
    }
}

object ScribeTheme {
    val colors: ScribeColors
